const e = $('Appel outil').first().json;
const n = s => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
let rows = $('Lignes').all().map(i => i.json).filter(r => r && r.client_id);
if (!rows.length) return [{ json: { resultat: 'Liste pas encore calculee (mise a jour chaque nuit).' } }];
const maj = rows.map(r => String(r.maj || '')).sort().pop();
rows = rows.filter(r => String(r.maj || '') === maj);
const mm = Number(e.mois_min) > 0 ? Number(e.mois_min) : 12;
rows = rows.filter(r => Number(r.mois) >= mm);
const villes = n(e.villes).split(',').map(s => s.trim()).filter(s => s && s !== 'tous' && s !== 'toutes');
if (villes.length) rows = rows.filter(r => villes.some(v => n(r.ville).includes(v) || n(r.adresse).includes(v)));
let g = null;
try { const x = $('Centre').first().json; if (e.client_id && x && x.lat !== null && x.lat !== undefined) g = x; } catch (err) {}
const rad = x => x * Math.PI / 180;
const km = (a, b, c, d) => { const h = Math.sin(rad(c - a) / 2) ** 2 + Math.cos(rad(a)) * Math.cos(rad(c)) * Math.sin(rad(d - b) / 2) ** 2; return 12742 * Math.asin(Math.sqrt(h)); };
if (g) {
  const R = Number(e.rayon_km) > 0 ? Number(e.rayon_km) : 3;
  rows = rows.filter(r => r.lat !== null && r.lat !== undefined).map(r => Object.assign({}, r, { km: Math.round(km(Number(g.lat), Number(g.lon), Number(r.lat), Number(r.lon)) * 10) / 10 })).filter(r => r.km <= R).sort((a, b) => a.km - b.km);
} else rows.sort((a, b) => Number(b.mois) - Number(a.mois));
const fr = d => d ? d.split('-').reverse().join('/') : '';
const entete = 'Clients avec une clim posee par ClimatPro et sans entretien depuis ' + mm + ' mois ou plus, hors contrat de maintenance' + (g ? ', a moins de ' + (Number(e.rayon_km) > 0 ? e.rayon_km : 3) + ' km de ' + g.nom : '') + (villes.length ? ', villes : ' + villes.join(', ') : '') + ' (historique Interfast depuis sept. 2023) : ' + rows.length + ' client(s).';
if (!rows.length) return [{ json: { resultat: entete } }];
const L = rows.slice(0, 25).map(r => '- ' + r.nom + ' | ' + (r.ville || '?') + (r.km !== undefined ? ' (' + r.km + ' km)' : '') + ' | pose le ' + fr(r.install_le) + ' : ' + r.install_objet + ' | entretien : ' + (r.dernier_entretien ? 'dernier le ' + fr(r.dernier_entretien) : 'jamais') + ' | ' + r.mois + ' mois sans entretien | client_id: ' + r.client_id);
return [{ json: { resultat: entete + '\n' + L.join('\n') + (rows.length > 25 ? '\n(25 premiers seulement, preciser une ville pour affiner)' : '') } }];
